// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 600, H = 450;
draw.viewbox(0, 0, W, H);

var pivot = { x: 170, y: 28 };
var L = 245;
var state = {
  theta: 25,
  forceModel: 'exact',
  animating: false,
  amp: 30,
  t0: 0,
