  currentStep: 0
};

var colors = {
  support: '#efd9ac',
  dash: '#333333',
  blue: '#244c82',
  red: '#d63f3f',
  green: '#2d8f58',
  gray: '#888888',
  light: '#eef7ff',
  small: '#ffe88a'
};

function polarPoint(angleDeg, radius, origin) {
  var a = angleDeg * Math.PI / 180;
  origin = origin || pivot;
  return { x: origin.x + radius * Math.sin(a), y: origin.y + radius * Math.cos(a) };
}
function rhat(angleDeg) {
  var a = angleDeg * Math.PI / 180;
  return { x: Math.sin(a), y: Math.cos(a) };
}
function that(angleDeg) {
  var a = angleDeg * Math.PI / 180;
  return { x: Math.cos(a), y: -Math.sin(a) };
}
function arcPoints(center, radius, a1, a2, n) {
  var pts = [];
  n = n || Math.max(8, Math.ceil(Math.abs(a2 - a1) / 3));
  for (var i = 0; i <= n; i++) {
    var a = a1 + (a2 - a1) * i / n;
    var p = polarPoint(a, radius, center);
    pts.push([p.x, p.y]);
  }
  return pts;
}
function ptsAttr(pts) {
  return pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
}
function haloText(txt, x, y, size, anchor) {
  return draw.text(txt).move(x, y).font({
    family: 'serif',
    size: size || 18,
    anchor: anchor || 'middle',
    style: 'italic'
  }).attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': 4,
    'stroke-linejoin': 'round',
    fill: '#222222'
  });
}
function makeArrow(color, width) {
  var g = draw.group();
  g.line(0, 0, 1, 1).stroke({ color: color, width: width || 4, linecap: 'round' });
  g.polygon('0,0 0,0 0,0').fill(color).stroke('none');
