}
function setArrow(g, x1, y1, x2, y2, color, width, headSize) {
  var line = g.get(0), head = g.get(1);
  var dx = x2 - x1, dy = y2 - y1;
  var len = Math.sqrt(dx * dx + dy * dy);
  color = color || '#000';
  width = width || 4;
  headSize = headSize || 13;
  if (len < 2) {
    g.hide();
    return;
  }
  g.show();
  var ux = dx / len, uy = dy / len;
  var bx = x2 - ux * headSize, by = y2 - uy * headSize;
  var px = -uy, py = ux;
  line.plot(x1, y1, x2 - ux * (headSize * 0.55), y2 - uy * (headSize * 0.55))
    .stroke({ color: color, width: width, linecap: 'round' });
