  }
];

function applyStep(i) {
  state.currentStep = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[state.currentStep];

  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (state.currentStep + 1) + ' / ' + demoSteps.length + ' — ' + step.title;

  var th = step.state.thetaAngle;
  document.getElementById('thetaAngleInput').value = th;
  document.getElementById('thetaAngleVal').value = th;

  var small = step.state.forceModel.indexOf('Small') === 0;
  document.getElementById('forceModelInput').checked = small;
  state.theta = th;
  state.amp = Math.max(1, Math.abs(th));
  toggle_forceModel(small);

  if (state.animating !== !!step.state.pendulumMotion) {
    toggle_pendulumMotion(!!step.state.pendulumMotion);
  }
  if (step.state.pendulumMotion) {
    state.amp = Math.max(5, Math.abs(th));
    state.t0 = performance.now();
  }
  refreshDiagram();
}
function nextStep() { applyStep(state.currentStep + 1); }
function prevStep() { applyStep(state.currentStep - 1); }

applyStep(0);
window.__markRendered();
